terms.medium_def:
People from Amor(?), first mentioned at Gen.10.16; 
only referred to as Amorites (אֱמֹרִי); 
descended from Canaan along with Sidon, Heth, Jebusites, Girgashites, Hivites, Arkites, Sinites, Arvadites, Zemarites and Hamathites. § one of the peoples of east Canaan and beyond the Jordan, dispossessed by the Israelite incursion from Egypt

A man of the Edomites living at the time of the Patriarchs, first mentioned at Gen.36.11; 
only referred to as Omar (אוֹמָר); 
son of Eliphaz; 
a brother of Teman, Zepho, Gatam, Kenaz, Amalek and Korah. § grandson of Esau

A priest from the tribe of Levi living at the time of Exile and Return, first mentioned at 1Ch.9.12; 
only referred to as Immer (אִמֵּר); 
father of Meshillemith.

A priest from the tribe of Levi living at the time of United Monarchy, first mentioned at 1Ch.6.7; 
only referred to as Amariah (אֲמַרְיָ֫הוּ); 
a son of Meraioth; 
father of Ahitub.

A High Priest from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.6.11; 
only referred to as Amariah (אֲמַרְיָ֫הוּ); 
a son of Azariah; 
father of Ahitub.

A man from the tribe of Levi living at the time of Egypt and Wilderness, first mentioned at 1Ch.23.19; 
only referred to as Amariah (אֲמַרְיָ֫הוּ); 
son of Hebron; 
a brother of Jeriah, Jahaziel and Jekameam.

A man living at the time of Exile and Return, only mentioned at Neh.3.29; 
only referred to as Immer (אִמֵּר); 
father of Zadok.

A man from the tribe of Judah living at the time of Exile and Return, only mentioned at 1Ch.9.4; 
only referred to as Imri (אִמְרִי); 
a son of Bani; 
father of Omri.

A man living at the time of Exile and Return, only mentioned at Neh.3.2; 
only referred to as Imri (אִמְרִי); 
father of Zaccur.

A man living at the time of Exile and Return, only mentioned at Neh.11.4; 
only referred to as Amariah (אֲמַרְיָ֫הוּ); 
a son of Shephatiah; 
father of Zechariah.

A man living at the time of Divided Monarchy, only mentioned at Zep.1.1; 
only referred to as Amariah (אֲמַרְיָ֫הוּ); 
a son of Hezekiah; 
father of Gedaliah.

A woman living at the time of United Monarchy, first mentioned at 1Sa.1.2; 
only referred to as Hannah (חַנָּה); 
wife of Elkanah; 
mother of Samuel. § the mother of Samuel, one of the wives of Elkanah

An Ammonite king living at the time of United Monarchy, first mentioned at 2Sa.10.1; 
only referred to as Hanun (חָנוּן); 
a son of Nahash.

A man living at the time of Divided Monarchy, first mentioned at Jer.28.1; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
a son of Azzur.

A prophet living at the time of Divided Monarchy, first mentioned at 1Ki.16.1; 
only referred to as Hanani (חֲנָנִי); 
father of Jehu.

A man from the tribe of Benjamin living at the time of Divided Monarchy, first mentioned at 1Ch.8.38; 
only referred to as Hanan (חָנָן); 
son of Azel; 
a brother of Azrikam, Bocheru, Ishmael, Sheariah and Obadiah.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.25.4; 
only referred to as Hanani (חֲנָנִי); 
son of Heman; 
a brother of Bukkiah, Mattaniah, Uzziel, Shebuel, Jerimoth, Hananiah, Eliathah, Giddalti, Romamti-ezer, Joshbekashah, Mallothi, Hothir, Mahazioth.

A man living at the time of Exile and Return, first mentioned at Neh.1.2; 
only referred to as Hanani (חֲנָנִי); 
son of Hacaliah; 
a brother of Nehemiah.

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.3.19; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
son of Zerubbabel; 
a brother of Meshullam, Shelomith, Hashubah, Ohel, Berechiah, Hasadiah, Jushab-hesed and Abiud; 
father of Pelatiah, Jeshaiah, Rephaiah, Arnan, Obadiah and Shecaniah.

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.25.4; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
son of Heman; 
a brother of Bukkiah, Mattaniah, Uzziel, Shebuel, Jerimoth, Hanani, Eliathah, Giddalti, Romamti-ezer, Joshbekashah, Mallothi, Hothir, Mahazioth.

A man living at the time of Exile and Return, first mentioned at Zec.6.10; 
referred to as Josiah (יֹאשִׁיָּ֫הוּ), or Hen (חֵן); 
a son of Zephaniah. § a contemporary of Zerubbabel

A man living at the time of Exile and Return, only mentioned at Neh.3.18; 
only referred to as Henadad (חֵנָדָד); 
father of Bavvai. § head of a family of Levites who took part in the rebuilding of the temple

A man living at the time of Exile and Return, only mentioned at Neh.3.24; 
only referred to as Henadad (חֵנָדָד); 
father of Binnui. § head of a family of Levites who took part in the rebuilding of the temple

A man living at the time of Exile and Return, only mentioned at Neh.3.30; 
only referred to as Hanun (חָנוּן); 
a son of Zalaph.

A man living at the time of Egypt and Wilderness, only mentioned at Num.34.23; 
only referred to as Hanniel (חַנִּיאֵל); 
a son of Ephod.

A man from the tribe of Asher living at the time of Divided Monarchy, only mentioned at 1Ch.7.39; 
only referred to as Hanniel (חַנִּיאֵל); 
son of Shual; 
a brother of Arah and Rizia.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.23; 
only referred to as Hanan (חָנָן); 
son of Shashak; 
a brother of Ishpan, Eber, Eliel, Abdon, Zichri, Hananiah, Elam, Anthothijah, Iphdeiah and Penuel.

A man living at the time of Divided Monarchy, only mentioned at 1Ch.11.43; 
only referred to as Hanan (חָנָן); 
a son of Maacah.

A man living at the time of Exile and Return, only mentioned at Neh.13.13; 
only referred to as Hanan (חָנָן); 
a son of Zaccur.

A man living at the time of Divided Monarchy, only mentioned at Jer.35.4; 
only referred to as Hanan (חָנָן); 
a son of Igdaliah.

A priest living at the time of Exile and Return, only mentioned at Neh.12.36; 
only referred to as Hanani (חֲנָנִי); 
son of Jonathan; 
a brother of Zechariah, Shemaiah, Azarel, Milalai, Gilalai, Maai, Nethanel and Judah.

A man living at the time of Exile and Return, only mentioned at Neh.3.30; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
a son of Shelemiah.

A man living at the time of Divided Monarchy, only mentioned at Jer.36.12; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
father of Zedekiah.

A man living at the time of Divided Monarchy, only mentioned at Jer.37.13; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
father of Shelemiah.

A man from the tribe of Benjamin living at the time of Divided Monarchy, only mentioned at 1Ch.8.24; 
only referred to as Hananiah (חֲנַנְיָ֫הוּ); 
son of Shashak; 
a brother of Ishpan, Eber, Eliel, Abdon, Zichri, Hanan, Elam, Anthothijah, Iphdeiah and Penuel.

A man from the tribe of Judah living at the time of Divided Monarchy, only mentioned at 1Ch.4.12; 
only referred to as Tehinnah (תְּחִנָּה); 
son of Eshton; 
a brother of Beth-rapha and Paseah; 
father or founder of Ir-nahash; 
founder of town Ir-nahash@1Ch.4.12; 
founder of Ge-harashim. § a Judaite, son of Eshton and father of Ir-Nahash

A man from the tribe of Judah living at the time of Divided Monarchy, first mentioned at 1Ch.2.37; 
only referred to as Ephlal (אֶפְלָל); 
a son of Zabad; 
father of Obed. § a descendant of Pharez

A man living at the time of Exile and Return, only mentioned at Neh.3.25; 
only referred to as Palal (פָּלָל); 
a son of Uzai. § son of Uzai and one who assisted in restoring the walls of Jerusalem in the time of Nehemiah

A priest living at the time of Exile and Return, only mentioned at Neh.11.12; 
only referred to as Pelaliah (פְּלַלְיָה); 
a son of Amzi; 
father of Jeroham. § son of Amzi and ancestor of Adaiah the priest in the time of Nehemiah

A king of Israel, from the tribe of Benjamin living at the time of United Monarchy, first mentioned at 1Sa.9.2; 
referred to as Saul (שָׁאוּל), or Saul (Σαούλ); 
a son of Kish; 
husband of Ahinoam and Rizpah; 
father of Jonathan, Abinadab, Malchi-shua, Merab, Michal, Ish-bosheth, Armoni, Mephibosheth.

A man from the tribe of Judah living at the time of Exile and Return, first mentioned at 1Ch.3.17; 
referred to as Shealtiel (שְׁאַלְתִּיאֵל), or Shealtiel (שַׁלְתִּיאֵל), or Shealtiel (Aramiac שְׁאַלְתִּיאֵל), or Shealtiel (Σαλαθιήλ); 
son of Jehoiachin; 
a brother of Zedekiah(?); 
father(?) of Malchiram, Pedaiah, Shenazzar, Jekamiah, Hoshama and Nedabiah. § son of king Jehoiachin or Jeconiah or Coniah of Judah and uncle of Zerubbabel

A man from the tribe of Simeon living at the time of Egypt and Wilderness, first mentioned at Gen.46.10; 
referred to as Shaul (שָׁאוּל), or Shaulite (שָׁאוּלִי); 
son of Simeon and Canaanite_woman; 
a brother of Jemuel, Jamin, Ohad, Jachin and Zerah; 
father of Shallum.

A man from the tribe of Judah living at the time of Exile and Return, first mentioned at 1Ch.3.17; 
referred to as Shealtiel (שְׁאַלְתִּיאֵל), or Shealtiel (שַׁלְתִּיאֵל), or Shealtiel (Aramiac שְׁאַלְתִּיאֵל), or Shealtiel (Σαλαθιήλ); 
son of Jehoiachin; 
a brother of Zedekiah(?); 
father(?) of Malchiram, Pedaiah, Shenazzar, Jekamiah, Hoshama and Nedabiah. § father of Zerubbabel

A man from the tribe of Levi living at the time of Divided Monarchy, first mentioned at 1Ch.6.24; 
referred to as Shaul (שָׁאוּל), or Joel (יוֹאֵל); 
a son of Uzziah; 
father of Elkanah.

A man from the tribe of Simeon living at the time of Egypt and Wilderness, first mentioned at Gen.46.10; 
referred to as Shaul (שָׁאוּל), or Shaulite (שָׁאוּלִי); 
son of Simeon and Canaanite_woman; 
a brother of Jemuel, Jamin, Ohad, Jachin and Zerah; 
father of Shallum. § Shaulites, of Saul "desired"
descendants of Saul or Shaul

A man living at the time of Egypt and Wilderness, first mentioned at Num.1.13; 
only referred to as Pagiel (פַּגְעִיאֵל); 
a son of Ochran. § son of Ocran and chief of the tribe of Asher at the time of the exodus

A man from the tribe of Manasseh living at the time of Egypt and Wilderness, first mentioned at Num.26.33; 
only referred to as Zelophehad (צְלׇפְחָד); 
a son of Hepher; 
father of Mahlah, Noah, Hoglah, Milcah and Tirzah. § a Manassite, son of Hepher and grandson of Gilead; came out of Egypt with Moses and died in the wilderness leaving only five daughters as heirs; their right to the inheritance was confirmed by divine direction

A man living at the time of Exile and Return, only mentioned at Neh.3.30; 
only referred to as Zalaph (צָלָף); 
father of Hanun. § father of Hanun who assisted in rebuilding the city wall of Jerusalem after the return from exile

A Judge living before Israel's Monarchy, first mentioned at Jdg.4.4; 
only referred to as Deborah (דְּבוֹרָה); 
wife of Lappidoth.

A man living at the time of Egypt and Wilderness, only mentioned at Lev.24.11; 
only referred to as Dibri (דִּבְרִי); 
father of Shelomith. § a Danite, father of Shelomith in the time of the exodus
